/** R4.14 current XDev project identity bootstrap.
 *
 * Establishes a NEW opaque XDev project id together with the existing R4.13
 * worker-external real control root. The candidate id is generated by XDev;
 * callers cannot supply a path-derived id, a historical id, a Host task id, or
 * an XMem UUID. The two-phase proposal/confirm flow is non-authorizing.
 *
 * The authoritative identity is the real-control-root identity.json. A copied
 * proposal and receipt bind the explicit confirmation to the root. Hashes bind
 * bytes only; management-root ACL quality remains a deployment responsibility.
 */
import {createHash,randomUUID} from 'node:crypto';
import {closeSync,existsSync,fsyncSync,lstatSync,mkdirSync,openSync,readFileSync,realpathSync,rmdirSync,writeFileSync} from 'node:fs';
import {dirname,isAbsolute,relative,resolve,sep,join} from 'node:path';
import {canonicalJson} from '../planning/governance-contracts.ts';
import {parseRfc3339Timestamp,parseUniqueJson} from '../planning/retry-history.ts';
import {controlNoLinks,readControlBytes} from './control-source-boundary.ts';
import {initializeRealControlRoot,inspectRealControlRoot,REAL_CONTROL_ROOT_ACK} from './real-control-root.ts';

export const PROJECT_IDENTITY_ACK='ESTABLISH_XDEV_PROJECT_IDENTITY_NO_PERMISSION';
export const PROJECT_IDENTITY_VALIDITY_MS=60*60*1000;

export type ProjectIdentityProposal={
  format:'xdev-project-identity-proposal-1';
  purpose:'ESTABLISH_XDEV_PROJECT_IDENTITY_AND_UNBOUND_CONTROL_ROOT';
  identity_root:string;
  workspace_root:string;
  candidate_project_id:string;
  prepared_at:string;
  valid_until:string;
  execution_permitted:false;
  reservation_created:false;
  worker_started:false;
  proposal_sha256:string;
};

type ProjectIdentityReceipt={
  format:'xdev-project-identity-receipt-1';
  state:'APPLIED';
  proposal_sha256:string;
  project_id:string;
  workspace_root:string;
  identity_sha256:string;
  real_control_root_id:string;
  applied_at:string;
  execution_permitted:false;
  reservation_created:false;
  worker_started:false;
};

const text=(v:unknown):v is string=>typeof v==='string'&&v.trim().length>0;
const sha=(v:unknown):v is string=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v);
function check(v:unknown,code:string):asserts v{if(!v)throw Error(code);}
function exact(v:any,keys:string[]){return v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).sort().join(',')===[...keys].sort().join(',');}
const digest=(v:unknown)=>createHash('sha256').update(canonicalJson(v as any)).digest('hex');
function canonicalAbs(p:string,code='PROJECT_IDENTITY_PATH_NOT_CANONICAL'){check(isAbsolute(p)&&resolve(p)===p,code);controlNoLinks(p);return p;}
function inside(root:string,p:string){const r=relative(root,p);return r===''||(!isAbsolute(r)&&r!=='..'&&!r.startsWith('..'+sep));}
function ordinaryDir(p:string,code:string){canonicalAbs(p);const s=lstatSync(p);check(s.isDirectory()&&!s.isSymbolicLink()&&realpathSync(p)===p,code);}
function writeNew(path:string,value:unknown){controlNoLinks(path);let fd:number|undefined;try{fd=openSync(path,'wx',0o600);writeFileSync(fd,canonicalJson(value as any));fsyncSync(fd);}finally{if(fd!==undefined)closeSync(fd);}}
function proposalCore(p:Omit<ProjectIdentityProposal,'proposal_sha256'>|ProjectIdentityProposal){const {proposal_sha256:_,...core}=p as ProjectIdentityProposal;return core;}
function projectId(v:unknown):v is string{return typeof v==='string'&&/^xdev-project:[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(v);}
function validateProposal(v:any):asserts v is ProjectIdentityProposal{
  const keys=['format','purpose','identity_root','workspace_root','candidate_project_id','prepared_at','valid_until','execution_permitted','reservation_created','worker_started','proposal_sha256'];
  check(exact(v,keys)&&v.format==='xdev-project-identity-proposal-1'&&v.purpose==='ESTABLISH_XDEV_PROJECT_IDENTITY_AND_UNBOUND_CONTROL_ROOT','PROJECT_IDENTITY_PROPOSAL_INVALID');
  check(projectId(v.candidate_project_id)&&sha(v.proposal_sha256)&&v.execution_permitted===false&&v.reservation_created===false&&v.worker_started===false,'PROJECT_IDENTITY_PROPOSAL_INVALID');
  const prepared=parseRfc3339Timestamp(v.prepared_at),until=parseRfc3339Timestamp(v.valid_until);check(prepared!==null&&until!==null&&until>prepared,'PROJECT_IDENTITY_PROPOSAL_TIME_INVALID');
  canonicalAbs(v.identity_root);canonicalAbs(v.workspace_root);check(!inside(v.workspace_root,v.identity_root)&&!inside(v.identity_root,v.workspace_root),'PROJECT_IDENTITY_WORKSPACE_OVERLAP');
  check(digest(proposalCore(v))===v.proposal_sha256,'PROJECT_IDENTITY_PROPOSAL_DIGEST_INVALID');
}
function validateReceipt(v:any):asserts v is ProjectIdentityReceipt{
  const keys=['format','state','proposal_sha256','project_id','workspace_root','identity_sha256','real_control_root_id','applied_at','execution_permitted','reservation_created','worker_started'];
  check(exact(v,keys)&&v.format==='xdev-project-identity-receipt-1'&&v.state==='APPLIED','PROJECT_IDENTITY_RECEIPT_INVALID');
  check(sha(v.proposal_sha256)&&projectId(v.project_id)&&text(v.workspace_root)&&sha(v.identity_sha256)&&text(v.real_control_root_id)&&parseRfc3339Timestamp(v.applied_at)!==null,'PROJECT_IDENTITY_RECEIPT_INVALID');
  check(v.execution_permitted===false&&v.reservation_created===false&&v.worker_started===false,'PROJECT_IDENTITY_RECEIPT_INVALID');
}
function ensureLayout(root:string,workspace:string,proposalPath?:string){
  canonicalAbs(root);canonicalAbs(workspace);ordinaryDir(workspace,'PROJECT_IDENTITY_WORKSPACE_INVALID');ordinaryDir(dirname(root),'PROJECT_IDENTITY_PARENT_INVALID');
  check(!inside(workspace,root)&&!inside(root,workspace),'PROJECT_IDENTITY_WORKSPACE_OVERLAP');
  if(proposalPath){canonicalAbs(proposalPath);ordinaryDir(dirname(proposalPath),'PROJECT_IDENTITY_PROPOSAL_PARENT_INVALID');check(!inside(workspace,proposalPath),'PROJECT_IDENTITY_PROPOSAL_IN_WORKSPACE');check(!inside(root,proposalPath),'PROJECT_IDENTITY_PROPOSAL_IN_TARGET_ROOT');}
}
function copyPaths(root:string){return{proposal:join(root,'identity-proposal.json'),receipt:join(root,'identity-bootstrap.json')};}

export function prepareProjectIdentity(identityRootInput:string,workspaceInput:string,outputInput:string,clock:()=>number=Date.now){
  const root=canonicalAbs(identityRootInput),workspace=canonicalAbs(workspaceInput),out=canonicalAbs(outputInput);ensureLayout(root,workspace,out);
  check(!existsSync(root),'PROJECT_IDENTITY_ROOT_EXISTS');check(!existsSync(out),'PROJECT_IDENTITY_PROPOSAL_OUTPUT_EXISTS');
  const now=clock();check(Number.isFinite(now)&&now>=0,'PROJECT_IDENTITY_TIME_INVALID');const until=now+PROJECT_IDENTITY_VALIDITY_MS;check(Number.isSafeInteger(until),'PROJECT_IDENTITY_TIME_INVALID');
  const core:Omit<ProjectIdentityProposal,'proposal_sha256'>={format:'xdev-project-identity-proposal-1',purpose:'ESTABLISH_XDEV_PROJECT_IDENTITY_AND_UNBOUND_CONTROL_ROOT',identity_root:root,workspace_root:workspace,candidate_project_id:'xdev-project:'+randomUUID(),prepared_at:new Date(now).toISOString(),valid_until:new Date(until).toISOString(),execution_permitted:false,reservation_created:false,worker_started:false};
  const proposal:ProjectIdentityProposal={...core,proposal_sha256:digest(core)};writeNew(out,proposal);
  return{status:'PROJECT_IDENTITY_PROPOSAL_PREPARED' as const,proposal_path:out,proposal_sha256:proposal.proposal_sha256,candidate_project_id:proposal.candidate_project_id,identity_root:root,workspace_root:workspace,valid_until:proposal.valid_until,execution_permitted:false,reservation_created:false,worker_started:false};
}

export async function applyProjectIdentity(proposalPathInput:string,confirmedDigest:string,ack:string,clock:()=>number=Date.now){
  check(ack===PROJECT_IDENTITY_ACK,'PROJECT_IDENTITY_EXPLICIT_ACK_REQUIRED');check(sha(confirmedDigest),'PROJECT_IDENTITY_CONFIRMATION_INVALID');
  const proposalPath=canonicalAbs(proposalPathInput),proposal=parseUniqueJson(readControlBytes(proposalPath).toString('utf8'));validateProposal(proposal);check(proposal.proposal_sha256===confirmedDigest,'PROJECT_IDENTITY_CONFIRMATION_MISMATCH');
  ensureLayout(proposal.identity_root,proposal.workspace_root,proposalPath);
  const root=proposal.identity_root,{proposal:proposalCopy,receipt:receiptPath}=copyPaths(root);
  if(existsSync(root)){
    if(!existsSync(proposalCopy)||!existsSync(receiptPath))throw Error('PROJECT_IDENTITY_PARTIAL_MANUAL_REVIEW_REQUIRED');
    const stored=parseUniqueJson(readControlBytes(proposalCopy).toString('utf8'));validateProposal(stored);const receipt=parseUniqueJson(readControlBytes(receiptPath).toString('utf8'));validateReceipt(receipt);
    check(stored.proposal_sha256===proposal.proposal_sha256&&receipt.proposal_sha256===proposal.proposal_sha256,'PROJECT_IDENTITY_ROOT_BOUND_TO_DIFFERENT_PROPOSAL');
    const status=await inspectProjectIdentity(root,clock);return{...status,status:'PROJECT_IDENTITY_ALREADY_APPLIED' as const};
  }
  const now=clock(),prepared=parseRfc3339Timestamp(proposal.prepared_at),until=parseRfc3339Timestamp(proposal.valid_until);check(Number.isFinite(now)&&prepared!==null&&until!==null&&now>=prepared&&now<until,'PROJECT_IDENTITY_PROPOSAL_EXPIRED_OR_CLOCK_INVALID');
  const lock=root+'.project-identity.lock';controlNoLinks(lock);let lockId:string|null=null;
  try{mkdirSync(lock,{mode:0o700});const s=lstatSync(lock);check(s.isDirectory()&&!s.isSymbolicLink(),'PROJECT_IDENTITY_LOCK_INVALID');lockId=`${s.dev}:${s.ino}`;}catch(e){if((e as NodeJS.ErrnoException).code==='EEXIST')throw Error('PROJECT_IDENTITY_BUSY_OR_OWNER_UNKNOWN');throw e;}
  try{
    // Re-read confirmed bytes after acquiring the management-side lock.
    const again=parseUniqueJson(readControlBytes(proposalPath).toString('utf8'));validateProposal(again);check(again.proposal_sha256===confirmedDigest&&canonicalJson(again as any)===canonicalJson(proposal as any),'PROJECT_IDENTITY_PROPOSAL_CHANGED');
    const deployed=initializeRealControlRoot(root,proposal.candidate_project_id,proposal.workspace_root,REAL_CONTROL_ROOT_ACK,clock);
    writeNew(proposalCopy,proposal);const real=await inspectRealControlRoot(root,clock);check(real.identity.project_id===proposal.candidate_project_id&&real.identity.workspace_root===proposal.workspace_root,'PROJECT_IDENTITY_REAL_ROOT_MISMATCH');
    const appliedAt=clock();check(Number.isFinite(appliedAt)&&appliedAt>=now,'PROJECT_IDENTITY_TIME_INVALID');const receipt:ProjectIdentityReceipt={format:'xdev-project-identity-receipt-1',state:'APPLIED',proposal_sha256:proposal.proposal_sha256,project_id:proposal.candidate_project_id,workspace_root:proposal.workspace_root,identity_sha256:deployed.identity_sha256,real_control_root_id:real.identity.root_id,applied_at:new Date(appliedAt).toISOString(),execution_permitted:false,reservation_created:false,worker_started:false};writeNew(receiptPath,receipt);
    return{status:'PROJECT_IDENTITY_ESTABLISHED_NOT_AUTHORIZED' as const,proposal_sha256:proposal.proposal_sha256,project_id:proposal.candidate_project_id,identity_root:root,real_control_root_status:real.status,execution_permitted:false,reservation_created:false,worker_started:false};
  }finally{
    const s=lstatSync(lock);check(s.isDirectory()&&!s.isSymbolicLink()&&`${s.dev}:${s.ino}`===lockId,'PROJECT_IDENTITY_LOCK_REPLACED');rmdirSync(lock);
  }
}

export async function inspectProjectIdentity(identityRootInput:string,clock:()=>number=Date.now){
  const root=canonicalAbs(identityRootInput);ordinaryDir(root,'PROJECT_IDENTITY_ROOT_INVALID');const {proposal:proposalPath,receipt:receiptPath}=copyPaths(root);
  check(existsSync(proposalPath)&&existsSync(receiptPath),'PROJECT_IDENTITY_PARTIAL_MANUAL_REVIEW_REQUIRED');
  const proposal=parseUniqueJson(readControlBytes(proposalPath).toString('utf8'));validateProposal(proposal);const receipt=parseUniqueJson(readControlBytes(receiptPath).toString('utf8'));validateReceipt(receipt);
  check(receipt.proposal_sha256===proposal.proposal_sha256&&receipt.project_id===proposal.candidate_project_id&&receipt.workspace_root===proposal.workspace_root,'PROJECT_IDENTITY_RECEIPT_BINDING_MISMATCH');
  const real=await inspectRealControlRoot(root,clock);check(real.identity.project_id===receipt.project_id&&real.identity.workspace_root===receipt.workspace_root&&real.identity.root_id===receipt.real_control_root_id,'PROJECT_IDENTITY_REAL_ROOT_MISMATCH');
  return{status:'PROJECT_IDENTITY_ESTABLISHED_NOT_AUTHORIZED' as const,project_id:receipt.project_id,workspace_root:receipt.workspace_root,identity_root:root,proposal_sha256:receipt.proposal_sha256,real_control_root_status:real.status,coverage:real.coverage,execution_permitted:false,reservation_created:false,worker_started:false};
}
